package com.ast.re4decomp;

/** Device-independent regression contracts for the M36 startup defects. */
public final class StartupPresentationTests {
  private static int checks;
  private static void check(boolean pass,String message){++checks;if(!pass)throw new AssertionError(message);}
  private static boolean near(float a,float b){return Math.abs(a-b)<.0001f;}
  public static void main(String[]args){
    StartupFlow flow=new StartupFlow();for(int i=0;i<78+585+70;++i)flow.tick();int entry=flow.menuFrame;flow.move(1);check(flow.menuFrame==entry,"Cursor move replayed entire entry fade");check(flow.cursorFrame==0&&flow.idle==0,"Cursor pulse/idle clocks did not restart");flow.move(-1);check(flow.menuFrame==entry,"Second cursor move changed root clock");flow.tick();check(flow.menuFrame==entry+1&&flow.cursorFrame==1,"Independent clocks did not advance");
    int title=flow.titleFrame(),pulse=flow.cursorFrame,textures=flow.titleTicks;
    flow.phase=StartupFlow.Phase.DEMO;flow.movieComplete();
    check(flow.phase==StartupFlow.Phase.MENU&&flow.titleFrame()==title&&flow.menuFrame==entry+1,"Demo rewound the authored title transition");
    check(flow.cursorFrame==pulse&&flow.titleTicks==textures,"Demo restarted live ID/texture clocks");
    check(flow.fade()==1&&flow.menuEntryFade()==0,"Demo return starts its own black fade");
    for(int n=1;n<=15;++n){flow.tick();check(near(flow.menuEntryFade(),n/15f),"Original fifteen-tick return fade");check(flow.titleFrame()==title+n,"Title transition must keep advancing after return");}
    flow.cursor=2;int before=flow.titleFrame();flow.confirm();flow.back();check(flow.phase==StartupFlow.Phase.MENU&&flow.titleFrame()==before,"Option return rewound the title");
    for(int demo=0;demo<3;++demo){int count=0;while(flow.phase==StartupFlow.Phase.MENU&&count++<600)flow.tick();check(flow.phase==StartupFlow.Phase.DEMO,"Idle demo did not start");int retained=flow.titleFrame();flow.movieComplete();check(flow.titleFrame()==retained&&flow.menuEntryFade()==0,"Repeated demo changed the retained title");}
    for(float[]size:new float[][]{{1920,1080},{2400,1080},{1280,1024},{640,360}})for(StartupFlow.Phase phase:new StartupFlow.Phase[]{StartupFlow.Phase.NINTENDO,StartupFlow.Phase.MENU,StartupFlow.Phase.OPTIONS,StartupFlow.Phase.LOAD}){StartupViewport v=new StartupViewport(size[0],size[1],phase);check(near(v.scaleX*640,size[0])&&near(v.scaleY*v.height,size[1]),"Picture letterboxed");check(near(v.sourceX(0),0)&&near(v.sourceX(size[0]),640),"Horizontal inverse touch transform");check(near(v.sourceY(0),v.top)&&near(v.sourceY(size[1]),v.top+v.height),"Vertical inverse touch transform");}
    for(int cursor=0;cursor<3;++cursor){check(StartupMath.menuVisible(2,cursor)&&StartupMath.menuVisible(4,cursor)&&StartupMath.menuVisible(6,cursor),"Unselected mirror/base labels disappeared");check(StartupMath.menuVisible(cursor==0?1:cursor==1?5:3,cursor)&&!StartupMath.menuVisible(cursor==0?5:1,cursor),"Wrong source selected highlight");}
    StartupMovieState movie=new StartupMovieState();movie.foreground(true);check(!movie.canPlay(),"Played without texture");long first=movie.attach();check(!movie.canPlay()&&!movie.presented(first),"Played/presented before decoder preparation");check(movie.prepared(first)&&movie.canPlay(),"Prepared visible decoder could not start");check(movie.presented(first)&&movie.hasPresented(),"Texture presentation missing");movie.foreground(false);check(!movie.canPlay(),"Background decoder kept playing");movie.foreground(true);check(movie.canPlay(),"Foreground decoder could not resume");movie.detach();check(!movie.canPlay()&&!movie.hasPresented(),"Lost texture kept playing/presented");long second=movie.attach();check(!movie.prepared(first)&&!movie.presented(first),"Old surface callbacks accepted");check(movie.prepared(second)&&movie.canPlay(),"Replacement surface could not prepare");movie.close();check(!movie.canPlay()&&!movie.current(second)&&!movie.prepared(second)&&movie.attach()==-1,"Closed decoder accepted late callbacks");
    float[] white={255,255,255,255},red={255,0,0,255};float[]same=StartupPixels.tint(white,red,new float[0][4],100,false);check(java.util.Arrays.equals(same,white),"Absent source colour curve interpolated using alpha255");float[]mixed=StartupPixels.tint(white,red,new float[][]{{0,0,0,0},{10,1,0,0}},5,false);check(near(mixed[1],127.5f)&&near(mixed[3],255),"Source normalized col0-col1 interpolation");
    check(StartupPixels.negative(0xff804020,0)==0xff7fbfdf,"Zero-power original negative omitted");check(StartupPixels.negative(0xff804020,1)==0xff007fbf,"Negative scale/clamp");check(StartupPixels.shimmerCoefficient(255,0)==27,"Original S0.10 indirect matrix coefficient");check(StartupPixels.shimmerOffset(27,255,false)>0&&StartupPixels.shimmerOffset(27,127,true)<0,"Unsigned/signed GX displacement");check(StartupPixels.shimmerOffset(0,255,false)==0,"Zero alpha still warped");
    int src=0xff808080,dst=0xff404040;check(StartupPixels.blend(src,dst,128,0)==0xff606060,"Source-alpha blend");check(StartupPixels.blend(src,dst,128,1)==0xff808080,"Alpha-scaled add blend");check(StartupPixels.blend(src,dst,128,2)==0xffc0c0c0,"Unscaled add blend2 collapsed to1");check(StartupPixels.blend(src,dst,128,3)==0xff606060,"Destination-colour plus destination blend");check(StartupPixels.blend(src,dst,128,4)==0xff202020,"Destination-colour multiply blend");check(StartupPixels.blend(src,dst,1,2)==dst,"Original alpha-test threshold");
    int[]corners={0xff000000,0xffff0000,0xff00ff00,0xffffffff};check(StartupPixels.sample(corners,2,2,.5f,.5f)==0xff808040,"Bilinear framebuffer copy sampling");check(StartupPixels.sample(corners,2,2,-1,-1)==corners[0]&&StartupPixels.sample(corners,2,2,99,99)==corners[3],"Framebuffer copy clamp");
    System.out.println("Startup presentation/movie lifecycle/source shader: "+checks+" checks PASS");
  }
}
